import { StyleSheet, } from 'react-native';

const styles = StyleSheet.create({
    container: {
        alignItems: 'center',
        position: 'absolute',
        backgroundColor: 'rgba(0,0,0,0.8)',
        borderRadius: 20,
        borderWidth: 3,
        borderColor: '#356',
        justifyContent: 'space-around',
        padding: 15,
    },

    listText: {
        fontSize: 40,
        color: '#000',
        backgroundColor: '#fff',
        padding: 5,
        borderRadius: 10,
        margin: 20

    },

    input: {
        textAlign: 'center',
        textAlignVertical: 'center',
        minHeight: 40,
        width: '100%',
        fontSize: 17,
        borderColor: 'gray',
        borderWidth: 2,
        backgroundColor: '#356',
        borderRadius: 10,
        color: '#fff'
    },

    payText: {
        color: '#fff',
        fontSize: 30,
        textAlign: 'center'
    },

    buttonPay: {
        backgroundColor: '#26A744',
        borderRadius: 15,
        width: '100%',
        padding: 10,
        marginTop: 15,
    }

});
export { styles };
